DeleteAccountState:
/**
 * Account deletion state and actions
 *
 * @version 0.1.0
 * @since 0.0.1
 * @author AMBROISE PARK Consulting
 */
export interface DeleteAccountState {
    /** Whether confirmation dialog is visible */
    showConfirmDialog: boolean;
    /** Whether account deletion is in progress */
    isDeleting: boolean;
    /** Whether password re-authentication dialog is visible */
    showPasswordDialog: boolean;
    /** Error message if any */
    error: string | null;
    /** Start the deletion flow (shows confirmation dialog) */
    startDeleteFlow: () => void;
    /** Confirm deletion (executes actual deletion, handles reauthentication internally) */
    confirmDelete: (password?: string) => Promise<void>;
    /** Cancel deletion flow (closes dialogs) */
    cancel: () => void;
}

subscribeToAuth:
/**
 * Subscribe to auth state changes
 * Use this in Zustand stores or other non-React contexts
 *
 * **Behavior:**
 * - Always returns unsubscribe function (never throws)
 * - Subscriptions work even if auth is not initialized
 * - On server, subscription is a no-op (returns empty unsubscribe function)
 * - Listener receives initial state immediately, then updates as auth state changes
 *
 * **Important:** Always call the returned unsubscribe function to prevent memory leaks.
 *
 * @param listener - Callback function that receives (state, prevState)
 * @returns Unsubscribe function (call to remove listener)
 *
 * @example
 * ```typescript
 * const unsubscribe = subscribeToAuth((state, prevState) => {
 *   if (state.user?.id !== prevState.user?.id) {
 *     // User changed - handle accordingly
 *     if (state.user) {
 *       console.log('User signed in:', state.user.id);
 *     } else {
 *       console.log('User signed out');
 *     }
 *   }
 * });
 *
 * // Later, cleanup
 * unsubscribe();
 * ```
 */
export declare function subscribeToAuth(listener: (state: AuthState & AuthActions, prevState: AuthState & AuthActions) => void): () => void;

