        requiredRole?: UserRole | UserRole[];
        requiredTier?: SubscriptionTier;
        requiresSubscription?: boolean;
        userRole?: UserRole;
        userTier?: SubscriptionTier;
        hasSubscription?: boolean;
    }>;
